-- 1. Which product type is currently contributing the most to overall revenue?
SELECT "Product type", SUM("Revenue generated") 
FROM "Data" 
GROUP BY "Product type" 
ORDER BY SUM("Revenue generated") DESC
LIMIT 1; 

-- 2. How much revenue is being generated by each supplier, and which suppliers are contributing the most?
SELECT "Supplier name", SUM("Revenue generated") 
FROM "Data" 
GROUP BY "Supplier name" 
ORDER BY SUM("Revenue generated") DESC; 

-- 3. Which transportation modes are associated with the highest overall costs?
SELECT "Transportation modes", SUM("Costs") 
FROM "Data" 
GROUP BY "Transportation modes" 
ORDER BY SUM("Costs") DESC; 

-- 4. Which product types are driving the highest sales volume?
SELECT "Product type", SUM("Number of products sold") AS "Total Products Sold" 
FROM "Data" 
GROUP BY "Product type" 
ORDER BY SUM("Number of products sold") DESC; 

-- 5. Which product types have the highest average manufacturing cost?
SELECT "Product type", AVG("Manufacturing costs") AS "Manufacturing Cost"
FROM "Data" 
GROUP BY "Product type" 
ORDER BY "Manufacturing Cost" DESC;

-- 6. What does the inspection outcome distribution look like, and which result occurs most frequently?
SELECT "Inspection results", COUNT("Inspection results")
FROM "Data" 
GROUP BY "Inspection results"
ORDER BY COUNT("Inspection results") DESC;

-- 7. Which product types show the highest average defect-rate metric?
SELECT "Product type", AVG("Defect rates")
FROM "Data" 
GROUP BY "Product type"
ORDER BY AVG("Defect rates") DESC;

-- 8. How do suppliers compare in terms of total revenue generated and products sold?
SELECT "Supplier name", SUM("Number of products sold"), SUM("Revenue generated")
FROM "Data" 
GROUP BY "Supplier name"
ORDER BY SUM("Revenue generated") DESC;

-- 9. Which product type is the strongest revenue contributor, and how does it perform in terms of sales volume and manufacturing cost?
SELECT "Product type", 
	SUM("Revenue generated") AS "Total Revenue",
	SUM("Number of products sold") AS "Total Products Sold",
	AVG("Manufacturing costs") AS "Avg Manufacturing cost"
FROM "Data" 
GROUP BY "Product type"
ORDER BY SUM("Revenue generated") DESC 
LIMIT 1;